// Import the required Node.js modules here
const http = require('http');
const fs = require('fs/promises');

// Create your HTTP server here
const server = http.createServer(requestHandler);

// Define your request handler function here
async function requestHandler(req, res) {
  // Parse URL parameters from the request
  const url = new URL(req.url, `http://${req.headers.host}`);
  const width = url.searchParams.get('width');
  const height = url.searchParams.get('height');

  // Add validation logic here
  if (!width || !height || isNaN(width) || isNaN(height)) {
    res.writeHead(400, { 'Content-Type': 'text/plain' });
    res.end('Invalid width or height parameters');
    return;
  }

  // Read the source image file here
  let imageBuffer;
  try {
    imageBuffer = await fs.readFile('./sample.jpg');
  } catch (err) {
    res.writeHead(404, { 'Content-Type': 'text/plain' });
    res.end('Source image not found');
    return;
  }

  // Resize the image using Sharp here
  const sharp = require('sharp');
  let resizedImage;
  try {
    resizedImage = await sharp(imageBuffer)
      .resize(parseInt(width), parseInt(height))
      .toBuffer();
  } catch (err) {
    res.writeHead(500, { 'Content-Type': 'text/plain' });
    res.end('Image processing failed');
    return;
  }

  // Send the resized image as response
  res.writeHead(200, { 'Content-Type': 'image/jpeg' });
  res.end(resizedImage);
}

